/**
 * Golden-parity test: replays every fixture in __fixtures__/metrics-golden.json
 * (generated by `node scripts/gen-metrics-fixtures.mjs`, which EXECUTES the
 * legacy packages/platform/qym_platform/_static/dashboard/metrics.js) against
 * the TypeScript port in metrics.ts and asserts value-identical results with
 * a 1e-12 relative float tolerance.
 *
 * The callback reconstruction below MUST stay in sync with the generator
 * script — both sides derive `getMetricIndex` / `getItemId` / `getRunId`
 * from the same declarative spec.
 */
import { describe, expect, it } from 'vitest'
import goldenJson from './__fixtures__/metrics-golden.json?raw'
import {
  calculateGroupedCohortComparison,
  calculateGroupedOutcomeBuckets,
  calculateItemLevelMetrics,
  calculateMedian,
  detectMetricType,
  detectMetricTypeFromAvg,
  formatLatency,
  formatMetricValue,
  formatMetricValueSmart,
  formatNumericValue,
  formatPercent,
  getMetricColorClass,
  getMetricTooltips,
  getRowScore,
  getScoreColorClass,
  isErrorRow,
  parseScoreValue,
  type RunData,
  type SnapshotRow,
} from './metrics'

// ---------------------------------------------------------------------------
// Fixture loading + tagged decoding ({"$undef":true}, {"$num":"nan"|...})
// ---------------------------------------------------------------------------

interface FixtureEntry {
  id: string
  kind: 'plain' | 'itemLevel' | 'grouped'
  fn: string
  args?: unknown[]
  spec?: Record<string, unknown>
  result: unknown
}

const fixtures: FixtureEntry[] = JSON.parse(goldenJson)

function decode(value: unknown): unknown {
  if (value === null || typeof value !== 'object') return value
  if (Array.isArray(value)) return value.map(decode)
  const obj = value as Record<string, unknown>
  if (obj.$undef === true) return undefined
  if (typeof obj.$num === 'string') {
    return obj.$num === 'nan' ? NaN : obj.$num === 'inf' ? Infinity : -Infinity
  }
  const out: Record<string, unknown> = {}
  for (const key of Object.keys(obj)) out[key] = decode(obj[key])
  return out
}

// ---------------------------------------------------------------------------
// Deep equality with float tolerance
// ---------------------------------------------------------------------------

const TOLERANCE = 1e-12

function assertDeepClose(actual: unknown, expected: unknown, path: string): void {
  if (typeof expected === 'number' && typeof actual === 'number') {
    if (Number.isNaN(expected)) {
      if (!Number.isNaN(actual)) throw new Error(`${path}: expected NaN, got ${actual}`)
      return
    }
    if (!Number.isFinite(expected)) {
      if (actual !== expected) throw new Error(`${path}: expected ${expected}, got ${actual}`)
      return
    }
    const allowed = TOLERANCE * Math.max(1, Math.abs(expected))
    if (Math.abs(actual - expected) > allowed) {
      throw new Error(`${path}: expected ${expected}, got ${actual} (diff > ${allowed})`)
    }
    return
  }
  if (Array.isArray(expected)) {
    if (!Array.isArray(actual)) throw new Error(`${path}: expected array, got ${typeof actual}`)
    if (actual.length !== expected.length) {
      throw new Error(`${path}: array length ${actual.length} !== ${expected.length}`)
    }
    expected.forEach((item, i) => assertDeepClose(actual[i], item, `${path}[${i}]`))
    return
  }
  if (expected !== null && typeof expected === 'object') {
    if (actual === null || typeof actual !== 'object' || Array.isArray(actual)) {
      throw new Error(`${path}: expected object, got ${JSON.stringify(actual)}`)
    }
    const expectedObj = expected as Record<string, unknown>
    const actualObj = actual as Record<string, unknown>
    const expectedKeys = Object.keys(expectedObj).sort()
    const actualKeys = Object.keys(actualObj).sort()
    if (expectedKeys.join(',') !== actualKeys.join(',')) {
      throw new Error(`${path}: keys [${actualKeys}] !== [${expectedKeys}]`)
    }
    for (const key of expectedKeys) {
      assertDeepClose(actualObj[key], expectedObj[key], `${path}.${key}`)
    }
    return
  }
  if (!Object.is(actual, expected)) {
    throw new Error(`${path}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`)
  }
}

// ---------------------------------------------------------------------------
// Spec -> callback reconstruction (MUST match gen-metrics-fixtures.mjs)
// ---------------------------------------------------------------------------

const getMetricIndexFromRun = (rd: RunData | null | undefined): number =>
  rd && typeof rd.metric_idx === 'number' ? rd.metric_idx : -1
const getItemIdByKey = (key: string) => (row: SnapshotRow) => String(row[key])
const groupedGetItemId = (row: SnapshotRow): string =>
  row.item_id == null ? '' : String(row.item_id)
const groupedGetRunId = (rd: RunData | null | undefined): string | undefined =>
  rd ? (rd.run_id as string | undefined) : undefined

type PlainFn = (...args: never[]) => unknown
const PLAIN_FNS: Record<string, PlainFn> = {
  isErrorRow,
  getRowScore,
  parseScoreValue,
  calculateMedian,
  detectMetricType,
  detectMetricTypeFromAvg,
  formatPercent,
  formatMetricValue,
  formatMetricValueSmart,
  formatNumericValue,
  formatLatency,
  getScoreColorClass,
  getMetricColorClass,
  getMetricTooltips,
} as unknown as Record<string, PlainFn>

function runFixture(entry: FixtureEntry): unknown {
  if (entry.kind === 'itemLevel') {
    const spec = decode(entry.spec) as {
      runsData: RunData[] | null
      metricName: string | null
      threshold: number
      itemIdKey: string | null
      trackDistribution: boolean
    }
    return calculateItemLevelMetrics({
      runsData: spec.runsData,
      metricName: spec.metricName ?? undefined,
      threshold: spec.threshold,
      getMetricIndex: getMetricIndexFromRun,
      getItemId: spec.itemIdKey ? getItemIdByKey(spec.itemIdKey) : undefined,
      trackDistribution: spec.trackDistribution,
    })
  }
  if (entry.kind === 'grouped') {
    const spec = decode(entry.spec) as {
      runsData: RunData[] | null
      leftRunIds: string[] | null
      rightRunIds: string[] | null
      threshold: number | null
      omitCallbacks: boolean
      nullOptions: boolean
    }
    const fn =
      entry.fn === 'calculateGroupedOutcomeBuckets'
        ? calculateGroupedOutcomeBuckets
        : calculateGroupedCohortComparison
    if (spec.nullOptions) return fn(null)
    return fn({
      runsData: spec.runsData,
      leftRunIds: spec.leftRunIds,
      rightRunIds: spec.rightRunIds,
      threshold: spec.threshold ?? undefined,
      getMetricIndex: spec.omitCallbacks ? undefined : getMetricIndexFromRun,
      getItemId: spec.omitCallbacks ? undefined : groupedGetItemId,
      getRunId: spec.omitCallbacks ? undefined : groupedGetRunId,
    })
  }
  const fn = PLAIN_FNS[entry.fn]
  if (!fn) throw new Error(`No TS function registered for fixture fn "${entry.fn}"`)
  const args = (entry.args ?? []).map(decode) as never[]
  return fn(...args)
}

// ---------------------------------------------------------------------------
// Replay every fixture
// ---------------------------------------------------------------------------

describe('metrics golden parity', () => {
  it('loaded a meaningful fixture grid', () => {
    expect(fixtures.length).toBeGreaterThan(200)
    const fns = new Set(fixtures.map((f) => f.fn))
    // Every exported legacy function must be covered.
    for (const name of [
      'isErrorRow',
      'getRowScore',
      'parseScoreValue',
      'calculateItemLevelMetrics',
      'calculateGroupedOutcomeBuckets',
      'calculateGroupedCohortComparison',
      'calculateMedian',
      'detectMetricType',
      'detectMetricTypeFromAvg',
      'formatPercent',
      'formatMetricValue',
      'formatMetricValueSmart',
      'formatNumericValue',
      'formatLatency',
      'getScoreColorClass',
      'getMetricColorClass',
      'getMetricTooltips',
    ]) {
      expect(fns, `fixture coverage for ${name}`).toContain(name)
    }
  })

  const byFn = new Map<string, FixtureEntry[]>()
  for (const entry of fixtures) {
    const list = byFn.get(entry.fn) ?? []
    list.push(entry)
    byFn.set(entry.fn, list)
  }

  for (const [fn, entries] of byFn) {
    describe(fn, () => {
      for (const entry of entries) {
        it(entry.id, () => {
          const actual = runFixture(entry)
          const expected = decode(entry.result)
          assertDeepClose(actual, expected, entry.id)
        })
      }
    })
  }
})
